package com.tekwatt.ocpp.controller;import com.tekwatt.ocpp.dto.*;import com.tekwatt.ocpp.service.OcppCommandService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/ocpp/commands")public class OcppCommandController{private final OcppCommandService service;public OcppCommandController(OcppCommandService s){service=s;}@PostMapping("/firmware")Map<String,String>firmware(@Valid@RequestBody FirmwareCommandRequest r){return Map.of("messageId",service.firmware(r));}@PostMapping("/remote-start")Map<String,String>remoteStart(@Valid@RequestBody RemoteStartRequest r){return Map.of("messageId",service.remoteStart(r));}@PostMapping("/remote-stop")Map<String,String>remoteStop(@Valid@RequestBody RemoteStopRequest r){return Map.of("messageId",service.remoteStop(r));}}
